// ─── Global Sleek Notice Modal Helper ────────────────────────────────────────
window.showSleekNoticeModal = function(title, htmlMessage, btnLabel, iconType) {
    var iconClass = 'bi-geo-alt-fill';
    var iconBg = '#fff1f0';
    var iconBorder = '#ffa39e';
    var iconColor = '#e02424';

    if (iconType === 'distance') {
        iconClass = 'bi-pin-map-fill';
        iconBg = '#fff7ed';
        iconBorder = '#ffedd5';
        iconColor = '#ea580c';
    } else if (iconType === 'time') {
        iconClass = 'bi-clock-history';
        iconBg = '#eff6ff';
        iconBorder = '#dbeafe';
        iconColor = '#2563eb';
    }

    if (typeof Swal === 'undefined') {
        alert(title + '\n\n' + htmlMessage.replace(/<[^>]+>/g, ''));
        return;
    }

    Swal.fire({
        width: '380px',
        padding: '1.25rem 1rem',
        html:
            '<div style="text-align:center;">' +
            '  <div style="width:46px;height:46px;background:' + iconBg + ';border:1.5px solid ' + iconBorder + ';border-radius:50%;display:inline-flex;align-items:center;justify-content:center;margin:0 auto 10px;">' +
            '    <i class="bi ' + iconClass + '" style="color:' + iconColor + ';font-size:22px;"></i>' +
            '  </div>' +
            '  <h5 style="font-weight:700;color:#1e293b;font-size:1.02rem;margin-bottom:8px;line-height:1.3;">' + title + '</h5>' +
            '  <div style="font-size:0.84rem;color:#475569;line-height:1.45;margin-bottom:14px;text-align:left;background:#f8fafc;padding:10px 12px;border-radius:10px;border:1px solid #f1f5f9;">' + htmlMessage + '</div>' +
            '  <button id="sleekSwalBtn" style="background:linear-gradient(135deg,#FC5D09,#ff4b2b);color:#fff;border:none;border-radius:8px;padding:9px 20px;font-weight:700;font-size:0.86rem;cursor:pointer;width:100%;box-shadow:0 4px 12px rgba(252,93,9,0.25);">' +
            (btnLabel || 'OK, Got It') +
            '  </button>' +
            '</div>',
        showConfirmButton: false,
        allowOutsideClick: true,
        customClass: {
            popup: 'sleek-swal-compact'
        },
        didOpen: function() {
            var btn = document.getElementById('sleekSwalBtn');
            if (btn) {
                btn.addEventListener('click', function() {
                    Swal.close();
                });
            }
        }
    });
};

// ─── State ─────────────────────────────────────────────────────────────────
var _isLoggedIn  = false;
var _pendingSubmit = false;
var _quoteOtpReqId = ''; // MSG91 reqId for Quote OTP modal
var _quoteMobile   = ''; // Mobile used in Quote OTP modal

// ─── Google Places Autocomplete validation flags ────────────────────────────
var _isPickupValidQuote = false; // true only when user picks from Google suggestions
var _isDropValidQuote   = false;

// ─── On Page Load: Check login status ─────────────────────────────────────
$(function () {
    $('#quoteOtpModal').appendTo('body');
    $('#citySelectionModal').appendTo('body');
    // Set min date
    var today = (function() { var d = new Date(); return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); })();
    var di = document.getElementById('service_shifting_date');
    if (di) { di.setAttribute('min', today); if (!di.value) di.value = today; }

    checkLoginStatus();

    // If the fields are pre-filled on page load (e.g. from session/city page), treat them as valid
    if ($('#service_movingfrom').val() && $('#service_movingfrom').val().trim().length > 1) {
        _isPickupValidQuote = true;
    }
    if ($('#service_movingTo').val() && $('#service_movingTo').val().trim().length > 1) {
        _isDropValidQuote = true;
    }

    // ─── OTP digit box auto-advance for Quote Modal ─────────────────────────
    $('.quote-otp-digit').on('input', function () {
        var val = $(this).val();
        if (val.length > 1) $(this).val(val.slice(-1));
        $(this).toggleClass('filled', val.length > 0);
        if (val.length === 1) {
            var next = $(this).next('.quote-otp-digit');
            if (next.length) next.focus();
        }
    }).on('keydown', function (e) {
        if (e.key === 'Backspace' && !$(this).val()) {
            var prev = $(this).prev('.quote-otp-digit');
            if (prev.length) prev.focus();
        }
    });

    // Hide T&C error on checkbox change
    $('#tc_agree_checkbox').on('change', function () {
        if ($(this).is(':checked')) {
            $('#tc_error_msg').fadeOut(150);
        }
    });

    // ─── Submit Form Click ──────────────────────────────────────────────────
    $('#submit_service_form1').click(function (e) {
        e.preventDefault();
        
        var name  = $('#form_user_name').val().trim();
        var mfrom = $('#service_movingfrom').val().trim();
        var mto   = $('#service_movingTo').val().trim();
        var phone = $('#service_form_phone').val().trim();
        var date  = $('#service_shifting_date').val().trim();
        var time  = $('#service_shifting_time').val().trim();

        if (!name || name.length < 2) {
            showSleekNoticeModal('Name Required', 'Please enter your full name.', 'Enter Name', 'location');
            $('#form_user_name').focus();
            return;
        }
        if (!mfrom) {
            showSleekNoticeModal('Pickup Location Required', 'Please enter a pickup location to get your moving quote.', 'Enter Pickup', 'location');
            $('#service_movingfrom').focus();
            return;
        }
        // ─── Validate Google Places selection for Pickup ───────────────────────
        if (!_isPickupValidQuote) {
            showSleekNoticeModal(
                'Select Pickup from Suggestions',
                'Please select your pickup location from the <b>suggestions dropdown list</b>, rather than typing manually.',
                'Select Suggestion',
                'location'
            );
            $('#service_movingfrom').focus();
            return;
        }

        // ─── Validate Pickup Location Restriction (Dynamic Admin Settings) ──────
        function isAllowedQuotePickup(addressStr) {
            if (!addressStr) return false;
            var str = addressStr.toLowerCase();
            var rawCities = window.allowedPickupCitiesStr || 'Delhi, Noida, Greater Noida, Gurugram, Gurgaon, Ghaziabad, Faridabad';
            var allowedKeywords = rawCities.split(',').map(function(c) { return c.trim().toLowerCase(); }).filter(function(c) { return c.length > 0; });
            
            var extraKeywords = [];
            allowedKeywords.forEach(function(kw) {
                if (kw === 'gurugram' || kw === 'gurgaon') {
                    extraKeywords.push('gurugram', 'gurgaon');
                } else if (kw === 'delhi' || kw === 'new delhi') {
                        extraKeywords.push('delhi', 'new delhi', 'ncr');
                } else if (kw === 'noida' || kw === 'greater noida') {
                    extraKeywords.push('noida', 'greater noida', 'gautam buddh', 'gautam budh');
                }
            });
            allowedKeywords = allowedKeywords.concat(extraKeywords);

            for (var i = 0; i < allowedKeywords.length; i++) {
                if (allowedKeywords[i] !== '' && str.indexOf(allowedKeywords[i]) !== -1) {
                    return true;
                }
            }
            return false;
        }

        if (!isAllowedQuotePickup(mfrom)) {
            var noticeCities = window.allowedPickupCitiesStr || 'Delhi, Noida, Greater Noida, Gurugram, Ghaziabad, Faridabad';
            showSleekNoticeModal(
                'Pickup Service Unavailable',
                'Currently, our pickup relocation service is available exclusively from <b>' + noticeCities + '</b>.<br><br>We do not offer pickup services from your selected location.',
                'Change Pickup Location',
                'location'
            );
            $('#service_movingfrom').focus();
            return;
        }

        if (!mto) {
            showSleekNoticeModal('Drop Location Required', 'Please enter a drop location to get your moving quote.', 'Enter Drop Location', 'location');
            $('#service_movingTo').focus();
            return;
        }
        // ─── Validate Google Places selection for Drop ────────────────────────
        if (!_isDropValidQuote) {
            showSleekNoticeModal(
                'Select Drop from Suggestions',
                'Please select your drop location from the <b>suggestions dropdown list</b>, rather than typing manually.',
                'Select Suggestion',
                'location'
            );
            $('#service_movingTo').focus();
            return;
        }
        if (!phone || phone.length !== 10 || !/^\d{10}$/.test(phone)) {
            showSleekNoticeModal('Mobile Required', 'Please enter a valid 10-digit mobile number.', 'Enter Mobile Number', 'location');
            $('#service_form_phone').focus();
            return;
        }
        if (!date) {
            showSleekNoticeModal('Date Required', 'Please select shifting date.', 'Select Date', 'time');
            $('#service_shifting_date').focus();
            return;
        }

        // ─── T&C Checkbox Validation ───────────────────────────────────────────
        if (!$('#tc_agree_checkbox').is(':checked')) {
            $('#tc_error_msg').fadeIn(200);
            return;
        } else {
            $('#tc_error_msg').hide();
        }
        // Save to localStorage for pre-filling online booking wizard
        var qData = {
            name: name,
            phone: phone,
            mfrom: mfrom,
            mto: mto,
            date: date,
            shifting_time: time
        };
        localStorage.setItem('bhandari_quote_data', JSON.stringify(qData));
        try {
            var bDraft = JSON.parse(localStorage.getItem('bhandari_booking_draft') || '{}');
            bDraft.pickup_location = mfrom;
            bDraft.drop_location = mto;
            bDraft.shifting_date = date;
            bDraft.shifting_time = time;
            bDraft.phone_number = phone;
            delete bDraft.distance_km;
            localStorage.setItem('bhandari_booking_draft', JSON.stringify(bDraft));
        } catch(e) {}

        // 1. Silent Background Submission to Admin immediately
        const formData = $('#service_form').serialize() + '&is_verified=0';
        $.ajax({
            type: 'POST',
            url: '<?php echo site_url("contacts/booking") ?>',
            data: formData,
            success: function (data) {
                console.log('Silent lead submission completed');
            }
        });

        // 2. If user is already logged in, redirect directly to item selection
        if (_isLoggedIn) {
            Swal.fire({
                title: '✅ Perfect!',
                text: "Now, let’s select your items.",
                icon: 'success',
                showConfirmButton: false,
                timer: 1500,
                timerProgressBar: true
            });
            setTimeout(function() {
                window.location.href = '<?= site_url("online-booking?status=success") ?>';
            }, 1000);
            return;
        }

        // 3. Otherwise, prepare OTP session & send OTP via browser-side MSG91 Widget
        _quoteMobile = phone;

        // Step 1: Prepare session on server (validates input, stores name/mobile)
        $.ajax({
            type: 'POST',
            url: '<?= site_url("user-auth/prepare-otp") ?>',
            data: { name: name, mobile: phone, returning: 0 },
            dataType: 'json',
            success: function (pr) {
                if (!pr.success) {
                    Swal.fire({ title: 'Error', text: pr.message || 'Failed to prepare OTP.', icon: 'error', confirmButtonColor: '#FC5D09' });
                    return;
                }
                // Step 2: Send OTP from browser directly to MSG91 Widget (no server IP, no IPBlocked)
                var mobile91 = '91' + phone;
                fetch('https://control.msg91.com/api/v5/widget/sendOtp', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ widgetId: '36686266774e343530343138', tokenAuth: '556182T8qj8j5D9j6a6f0ae7P1', identifier: mobile91 })
                })
                .then(function(res) { return res.json(); })
                .then(function(data) {
                    if (data && data.type === 'success' && data.message) {
                        _quoteOtpReqId = data.message;
                    } else {
                        _quoteOtpReqId = '';
                    }
                    // Close any leftover Swal overlay before opening Bootstrap modal
                    if (typeof Swal !== 'undefined') Swal.close();
                    $('#quoteOtpMaskedMobile').text('+91 \u2022\u2022\u2022\u2022\u2022\u2022' + phone.slice(-4));
                    $('.quote-otp-digit').val('').removeClass('filled');
                    $('#quoteOtpError').addClass('d-none').text('');
                    // Remove any stale backdrops
                    $('.modal-backdrop').remove();
                    $('body').removeClass('modal-open').css({'overflow':'','padding-right':''});
                    var modal = new bootstrap.Modal(document.getElementById('quoteOtpModal'));
                    modal.show();
                })
                .catch(function() {
                    _quoteOtpReqId = '';
                    if (typeof Swal !== 'undefined') Swal.close();
                    $('#quoteOtpMaskedMobile').text('+91 \u2022\u2022\u2022\u2022\u2022\u2022' + phone.slice(-4));
                    $('.quote-otp-digit').val('').removeClass('filled');
                    $('#quoteOtpError').addClass('d-none').text('');
                    $('.modal-backdrop').remove();
                    $('body').removeClass('modal-open').css({'overflow':'','padding-right':''});
                    var modal = new bootstrap.Modal(document.getElementById('quoteOtpModal'));
                    modal.show();
                });
            },
            error: function () {
                Swal.fire({ title: 'Connection Error', text: 'Unable to send OTP. Please try again.', icon: 'error', confirmButtonColor: '#FC5D09' });
            }
        });
    });

    // Verify OTP button in Quote OTP Modal
    $('#btnVerifyQuoteOtp').click(function () {
        var otp = '';
        $('.quote-otp-digit').each(function () { otp += $(this).val(); });
        
        if (otp.length < 6) {
            $('#quoteOtpError').removeClass('d-none').text('Please enter the full 6-digit OTP.');
            return;
        }

        $('#quoteOtpError').addClass('d-none');
        var btn = $(this);
        btn.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-1"></span> Verifying...');

        function doServerVerify(browserVerified) {
            $.ajax({
                type: 'POST',
                url: '<?= site_url("user-auth/verify-otp") ?>',
                data: { otp: otp, req_id: _quoteOtpReqId || '', browser_verified: browserVerified ? 1 : 0 },
                dataType: 'json',
                success: function (r) {
                    btn.prop('disabled', false).html('<i class="bi bi-check-circle-fill me-1"></i> Verify OTP & Submit');
                    if (r.success) {
                        _isLoggedIn = true;
                        _quoteOtpReqId = '';
                        var modalEl = document.getElementById('quoteOtpModal');
                        var modal = bootstrap.Modal.getInstance(modalEl);
                        if (modal) modal.hide();
                        submitBooking(1);
                    } else {
                        $('#quoteOtpError').removeClass('d-none').text(r.message || 'Invalid OTP.');
                    }
                },
                error: function () {
                    btn.prop('disabled', false).html('<i class="bi bi-check-circle-fill me-1"></i> Verify OTP & Submit');
                    $('#quoteOtpError').removeClass('d-none').text('Server error. Please try again.');
                }
            });
        }

        // If we have a MSG91 reqId, verify browser-side first
        if (_quoteOtpReqId) {
            fetch('https://control.msg91.com/api/v5/widget/verifyOtp', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ widgetId: '36686266774e343530343138', tokenAuth: '556182T8qj8j5D9j6a6f0ae7P1', reqId: _quoteOtpReqId, otp: otp })
            })
            .then(function(res) { return res.json(); })
            .then(function(data) {
                doServerVerify(data && data.type === 'success');
            })
            .catch(function() {
                doServerVerify(false);
            });
        } else {
            // No reqId (widget send failed), use session-based server OTP
            doServerVerify(false);
        }
    });

    // Skip OTP button in Quote OTP Modal
    $('#btnSkipQuoteOtp').click(function () {
        var modalEl = document.getElementById('quoteOtpModal');
        var modal = bootstrap.Modal.getInstance(modalEl);
        if (modal) modal.hide();
        submitBooking(0);
    });
});

// Resend OTP for Quote OTP Modal
function resendQuoteOtp() {
    if (!_quoteMobile) return;
    var btn = document.getElementById('btnResendQuoteOtp');
    if (btn) { btn.disabled = true; btn.textContent = 'Sending...'; }

    var mobile91 = '91' + _quoteMobile;
    fetch('https://control.msg91.com/api/v5/widget/sendOtp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ widgetId: '36686266774e343530343138', tokenAuth: '556182T8qj8j5D9j6a6f0ae7P1', identifier: mobile91 })
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        if (btn) { btn.disabled = false; btn.textContent = 'Resend OTP'; }
        if (data && data.type === 'success' && data.message) {
            _quoteOtpReqId = data.message;
            $('.quote-otp-digit').val('').removeClass('filled').first().focus();
            $('#quoteOtpError').addClass('d-none');
            // Show success toast
            if (typeof Swal !== 'undefined') {
                Swal.fire({ toast: true, position: 'top-end', icon: 'success', title: 'New OTP sent!', showConfirmButton: false, timer: 3000 });
            }
        } else {
            if (typeof Swal !== 'undefined') {
                Swal.fire({ toast: true, position: 'top-end', icon: 'warning', title: 'Could not resend. Try again.', showConfirmButton: false, timer: 3000 });
            }
        }
    })
    .catch(function() {
        if (btn) { btn.disabled = false; btn.textContent = 'Resend OTP'; }
    });
}

// ─── Submit Booking (Free Quote Inquiry) ──────────────────────────────────
function submitBooking(isVerified) {
    var isVer = (isVerified === 1 || isVerified === '1');
    
    if (isVer) {
        Swal.fire({
            title: '✅ Verification Successful!',
            text: "Now, let’s select your items.",
            allowOutsideClick: false,
            showConfirmButton: false,
            didOpen: function() { Swal.showLoading(); }
        });
    }

    const formData = $('#service_form').serialize() + '&is_verified=' + (isVer ? '1' : '0');

    $.ajax({
        type: 'POST',
        url: '<?php echo site_url("contacts/booking") ?>',
        data: formData,
        success: function (data) {
            var trimmedData = (typeof data === 'string') ? data.trim() : String(data).trim();
            if (trimmedData === '1' || trimmedData.indexOf('1') === 0) {
                $('#service_form')[0].reset();
                var today = (function() { var d = new Date(); return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); })();
                var dateEl = document.getElementById('service_shifting_date');
                if (dateEl) dateEl.value = today;

                if (isVer) {
                    // Verified user: proceed to item selection page
                    window.location.href = '<?= site_url("online-booking?status=success") ?>';
                } else {
                    // Unverified / Skipped OTP: stay on home page and show confirmation alert
                    Swal.fire({
                        title: 'Quote Request Received! 🙏',
                        html: 'Thank you for your request! Our team will review your moving details and contact you shortly.',
                        icon: 'success',
                        confirmButtonText: 'OK, Got It',
                        confirmButtonColor: '#FC5D09'
                    });
                }
            } else {
                var cleanMsg = $('<div>').html(data).text().trim() || data;
                Swal.fire({
                    title: 'Error!',
                    text: cleanMsg,
                    icon: 'error',
                    confirmButtonText: 'OK',
                    confirmButtonColor: '#FC5D09'
                });
            }
        },
        error: function() {
            Swal.fire({ title:'Network Error', text:'Something went wrong.', icon:'error', confirmButtonColor:'#FC5D09' });
        }
    });
}

// ── Location Autocomplete for Service Form ───────
function setupServiceLocationAutocomplete(inputId, suggestionsId, onSelectCallback) {
    let timer = null;
    const $input = $('#' + inputId);
    const $suggestions = $('#' + suggestionsId);

    // Google Maps services lazy loaded variables
    let autocompleteService = null;

    $input.on('keyup input focus', function () {
        clearTimeout(timer);
        if ($input.data('just-selected')) {
            $input.data('just-selected', false);
            $suggestions.hide();
            return;
        }
        const query = $(this).val().trim();
        if (query.length < 2) {
            $suggestions.hide().empty();
            return;
        }

        // Lazy initialize Google Maps services
        if (typeof google !== 'undefined' && google.maps && google.maps.places) {
            if (!autocompleteService) autocompleteService = new google.maps.places.AutocompleteService();
        }

        if (!autocompleteService) {
            console.error('Google Maps API or Places library not loaded.');
            return;
        }

        timer = setTimeout(function () {
            autocompleteService.getPlacePredictions({
                input: query,
                componentRestrictions: { country: 'in' } // restrict to India
            }, function (predictions, status) {
                $suggestions.empty();
                if (status !== google.maps.places.PlacesServiceStatus.OK || !predictions || predictions.length === 0) {
                    $suggestions.hide();
                    return;
                }

                $.each(predictions, function (i, prediction) {
                    const mainTitle = prediction.structured_formatting.main_text || '';
                    const subTitle = prediction.structured_formatting.secondary_text || '';
                    const fullName = prediction.description;

                    const $item = $(
                        '<a href="#" class="dropdown-item py-2 px-3 border-bottom d-flex align-items-center gap-2" style="white-space:normal;">' +
                            '<div class="flex-shrink-0 bg-danger-subtle text-danger rounded-circle p-2 d-flex align-items-center justify-content-center" style="width:32px;height:32px;">' +
                                '<i class="bi bi-geo-alt-fill text-danger"></i>' +
                            '</div>' +
                            '<div class="flex-grow-1 overflow-hidden">' +
                                '<div class="fw-bold text-dark small text-truncate">' + mainTitle + '</div>' +
                                (subTitle ? '<div class="text-muted extra-small text-truncate" style="font-size:0.75rem;">' + subTitle + '</div>' : '') +
                            '</div>' +
                        '</a>'
                    );

                    $item.on('click', function (e) {
                        e.preventDefault();
                        $input.data('just-selected', true);
                        $input.val(fullName);
                        $suggestions.hide().empty();
                        // Mark as valid via callback (sets the validation flag)
                        if (typeof onSelectCallback === 'function') onSelectCallback();
                    });

                    $suggestions.append($item);
                });
                $suggestions.show();
            });
        }, 250);
    });

    // Reset the flag when user types new text
    $input.on('input', function() {
        if (typeof onSelectCallback === 'function' && !$input.data('just-selected')) {
            // Typing — mark invalid until they pick again
            if (inputId === 'service_movingfrom') _isPickupValidQuote = false;
            if (inputId === 'service_movingTo')   _isDropValidQuote   = false;
        }
    });

    $(document).on('click', function (e) {
        if (!$(e.target).closest('#' + inputId + ', #' + suggestionsId).length) {
            $suggestions.hide();
        }
    });
}

setupServiceLocationAutocomplete('service_movingfrom', 'service_pickup_suggestions', function() { _isPickupValidQuote = true; });
setupServiceLocationAutocomplete('service_movingTo', 'service_drop_suggestions', function() { _isDropValidQuote = true; });

$(document).ready(function() {
    if (window.location.hash === '#quote-form-section' || window.location.hash === '#quote_form' || window.location.hash === '#instant-quote-form') {
        setTimeout(function() {
            var $target = $('#quote-form-section');
            if ($target.length) {
                $('html, body').animate({
                    scrollTop: $target.offset().top - 80
                }, 500);
                $('#form_user_name').focus();
            }
        }, 300);
    }
});

